create or replace function private.statement_row_fingerprint_v2(p_transaction_date date,p_value_date date,p_reference text,p_signed_amount numeric,p_narration text,p_counterparty text,p_running_balance numeric) returns text language sql immutable set search_path='' as $$ select encode(extensions.digest(concat_ws('|',coalesce(p_transaction_date::text,''),coalesce(p_value_date::text,''),regexp_replace(regexp_replace(lower(trim(coalesce(p_reference,''))),'\s+',' ','g'),'[^a-z0-9 ._\-/]','','g'),regexp_replace(regexp_replace(coalesce(p_signed_amount::text,''),'(\.[0-9]*?)0+$','\1'),'\.$',''),regexp_replace(regexp_replace(lower(trim(coalesce(p_narration,''))),'\s+',' ','g'),'[^a-z0-9 ._\-/]','','g'),regexp_replace(regexp_replace(lower(trim(coalesce(p_counterparty,''))),'\s+',' ','g'),'[^a-z0-9 ._\-/]','','g'),regexp_replace(regexp_replace(coalesce(p_running_balance::text,''),'(\.[0-9]*?)0+$','\1'),'\.$','')),'sha256'),'hex'); $$;
create or replace function private.set_statement_row_fingerprint_v2() returns trigger language plpgsql security definer set search_path='' as $$ begin new.normalized_fingerprint:=private.statement_row_fingerprint_v2(new.transaction_date,new.value_date,new.reference,new.signed_amount,new.narration,new.counterparty,new.running_balance);return new;end;$$;
drop trigger if exists trg_statement_rows_fingerprint_v2 on public.statement_rows;
create trigger trg_statement_rows_fingerprint_v2 before insert or update of transaction_date,value_date,reference,signed_amount,narration,counterparty,running_balance on public.statement_rows for each row execute function private.set_statement_row_fingerprint_v2();
update public.statement_rows sr set normalized_fingerprint=private.statement_row_fingerprint_v2(sr.transaction_date,sr.value_date,sr.reference,sr.signed_amount,sr.narration,sr.counterparty,sr.running_balance);
update public.canonical_transactions ct set normalized_fingerprint=sr.normalized_fingerprint,updated_at=now() from public.statement_row_transaction_links l join public.statement_rows sr on sr.id=l.statement_row_id where l.canonical_transaction_id=ct.id and l.is_primary=true and ct.reversed_at is null;
revoke all on function private.statement_row_fingerprint_v2(date,date,text,numeric,text,text,numeric) from public;
revoke all on function private.set_statement_row_fingerprint_v2() from public;
